-- Generated by fedora-nothing from the displays connected at install time.
-- Re-run `install.sh --only=hyprland` after changing your monitor setup.
--
-- Returns a table rather than setting globals: Hyprland evaluates each config
-- file in its own environment, so globals do not cross file boundaries.
--
--   per_monitor  workspaces each output owns
--   order        outputs in workspace order; the first gets 1..per_monitor
--   vertical     outputs whose scrolling tape runs vertically
return {
	per_monitor = 10,
	order = { "@@MONITOR@@" },
	vertical = {},
}
